INSERT INTO `edu_chn_word_sense`
(`id`, `word_class`, `word`, `pinyin`, `meaning`, `example`, `source`, `example_trans`, `status`, `is_del`)
VALUES
(1, 1, '劝', 'quàn', '<动>勉励，鼓励', NULL, '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '附件将“劝”列入《劝学》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(2, 1, '疾', 'jí', '<形>快，速', '顺风而呼，声非加<b>疾</b>也，而闻者彰。', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '顺风呼喊，声音没有加大，但听到的人觉得清楚。', 1, 0),
(3, 1, '彰', 'zhāng', '<形>明显，清楚', '顺风而呼，声非加疾也，而闻者<b>彰</b>。', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '顺风呼喊，声音没有加大，但听到的人觉得清楚。', 1, 0),
(4, 1, '假', 'jiǎ', '<动>借助，利用', '<b>假</b>舆马者，非利足也，而致千里；', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '借助车马的人，脚并不快，却能到达千里；', 1, 0),
(5, 1, '绝', 'jué', '<动>横渡', '假舟楫者，非能水也，而<b>绝</b>江河。', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '借助船和桨的人，并不善于游泳，却能横渡江河。', 1, 0),
(6, 1, '积', 'jī', '<动>堆积，积累', '<b>积</b>土成山，风雨兴焉；', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '堆积土石成为高山，风雨从那里兴起；', 1, 0),
(7, 1, '锲', 'qiè', '<动>刻，雕刻', '<b>锲</b>而舍之，朽木不折；', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '雕刻如果半途而废，腐朽的木头也刻不断；', 1, 0),
(8, 1, '舍', 'shě', '<动>停止，放弃', '驽马十驾，功在不<b>舍</b>。', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '劣马拉车走十天，功效在于不停。', 1, 0),
(9, 1, '兴', 'xīng', '<动>兴起', '积土成山，风雨<b>兴</b>焉；', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '堆积土石成为高山，风雨从那里兴起；', 1, 0),
(10, 1, '望', 'wàng', '<动>远看', '吾尝跂而<b>望</b>矣，不如登高之博见也。', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '我曾踮起脚跟远望，不如登高看得广。', 1, 0),
(11, 1, '知', 'zhì', '<通假>同“智”，智慧', '故木受绳则直，金就砺则利，君子博学而日参省乎己，则<b>知</b>明而行无过矣。', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '所以木材用墨线量过就直，刀剑等金属靠近磨刀石就锋利，君子广泛学习并且每天检查反省自己，就能智慧明达、行为没有过错。', 1, 0),
(12, 2, '而', 'ér', '<连>表转折，却', '青，取之于蓝，<b>而</b>青于蓝；', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '靛青从蓼蓝中取得，却比蓼蓝颜色更深；', 1, 0),
(13, 2, '于', 'yú', '<介>介词，从', '青，取之<b>于</b>蓝，而青<b>于</b>蓝；', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '靛青从蓼蓝中取得，却比蓼蓝颜色更深；', 1, 0),
(14, 2, '之', 'zhī', '<代>代词，它，指青', '青，取<b>之</b>于蓝，而青于蓝；', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '靛青从蓼蓝中取得，却比蓼蓝颜色更深；', 1, 0),
(15, 2, '者', 'zhě', '<助>……的人', '虽有槁暴，不复挺<b>者</b>，輮使之然也。', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '即使又晒干，也不会再挺直，这是火烤使它变成这样的。', 1, 0),
(16, 2, '也', 'yě', '<助>表判断，是', '虽有槁暴，不复挺者，輮使之然<b>也</b>。', '部编版｜高中必修上册｜第五单元（课内）｜《劝学》', '即使又晒干，也不会再挺直，这是火烤使它变成这样的。', 1, 0),
(17, 1, '师', 'shī', '<意动>以……为师，意动用法', '古之学者必有<b>师</b>。', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '古代求学的人一定有老师。', 1, 0),
(18, 1, '惑', 'huò', '<名>疑惑，疑难问题', '师者，所以传道受业解<b>惑</b>也。', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '老师，是用来传授道理、教授学业、解答疑难问题的人。', 1, 0),
(19, 1, '传', 'chuán', '<名>传授的知识', '师者，所以<b>传</b>道受业解惑也。', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '老师，是用来传授道理、教授学业、解答疑难问题的人。', 1, 0),
(20, 1, '从', 'cóng', '<动>跟随', '惑而不<b>从</b>师，其为惑也，终不解矣。', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '有疑惑却不跟从老师学习，那些疑惑最终也不能解决。', 1, 0),
(21, 1, '贤', 'xián', '<动>超过，胜过', '是故弟子不必不如师，师不必<b>贤</b>于弟子，闻道有先后，术业有专攻，如是而已。', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '因此学生不一定不如老师，老师也不一定比学生贤能，听闻道理有先有后，学术技艺各有专门研究，如此而已。', 1, 0),
(22, 1, '益', 'yì', '<副>更加', '是故圣<b>益</b>圣，愚<b>益</b>愚。', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '圣人之所以圣明、愚人之所以愚昧，大概都出于这个原因吧？', 1, 0),
(23, 1, '穷', 'qióng', '<形>困窘，处境困难', NULL, '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '附件将“穷”列入《师说》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(24, 1, '通', 'tōng', '<形>通晓，明白', '李氏子蟠，年十七，好古文，六艺经传皆<b>通</b>习之，不拘于时，学于余。', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '李家的孩子蟠，十七岁，喜欢古文，六经的经文和传文都普遍学习了，不受时俗拘束，向我学习。', 1, 0),
(25, 1, '达', 'dá', '<形>通达，得志', NULL, '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '附件将“达”列入《师说》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(26, 2, '之', 'zhī', '<助>助词，的', '古<b>之</b>学者必有师。', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '古代求学的人一定有老师。', 1, 0),
(27, 2, '其', 'qí', '<代>代词，他的', '惑而不从师，<b>其</b>为惑也，终不解矣。', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '有疑惑却不跟从老师学习，那些疑惑最终也不能解决。', 1, 0),
(28, 2, '而', 'ér', '<连>表转折，却', '人非生<b>而</b>知之者，孰能无惑？', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '人不是生来就懂得道理的，谁能没有疑惑？', 1, 0),
(29, 2, '于', 'yú', '<介>介词，向、对', '吾师道也，夫庸知其年之先后生<b>于</b>吾乎？', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '我学习的是道理，哪里要了解他的年龄比我大还是小呢？', 1, 0),
(30, 2, '乎', 'hū', '<语气>表反问，吗', '生<b>乎</b>吾前，其闻道也固先<b>乎</b>吾，吾从而师之；', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '出生在我前面的人，他懂得道理本来就比我早，我跟从他把他当作老师；', 1, 0),
(31, 2, '所', 'suǒ', '<助>与“以”组成“所以”，表示用来……的', '师者，<b>所</b>以传道受业解惑也。', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '老师，是用来传授道理、教授学业、解答疑难问题的人。', 1, 0),
(32, 2, '则', 'zé', '<连>表转折，却', '于其身也，<b>则</b>耻师焉，惑矣。', '部编版｜高中必修上册｜第五单元（课内）｜《师说》', '对于自己，却以从师学习为可耻，真是糊涂。', 1, 0),
(33, 1, '逝', 'shì', '<动>流逝', '<b>逝</b>者如斯，而未尝往也；', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '流逝的水像这样，却未曾真正流走；', 1, 0),
(34, 1, '盈', 'yíng', '<形>满', '<b>盈</b>虚者如彼，而卒莫消长也。', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '月有圆缺像那样，但终究没有增减。', 1, 0),
(35, 1, '虚', 'xū', '<形>空', '浩浩乎如冯<b>虚</b>御风，而不知其所止；', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '飘飘然像脱离尘世、独立存在，飞升成仙。', 1, 0),
(36, 1, '取', 'qǔ', '<动>取得，获得', '且夫天地之间，物各有主，苟非吾之所有，虽一毫而莫<b>取</b>。', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '况且天地之间万物各有主人，如果不是我所有，即使一丝一毫也不能取用。', 1, 0),
(37, 1, '望', 'wàng', '<名>农历每月十五日', '壬戌之秋，七月既<b>望</b>，苏子与客泛舟游于赤壁之下。', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '壬戌年秋，七月十六日，苏轼和友人在赤壁下泛舟游览。', 1, 0),
(38, 1, '如', 'rú', '<动>往，去', '纵一苇之所<b>如</b>，凌万顷之茫然。', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '任凭小船漂到哪里，越过茫茫万顷的江面，浩浩荡荡仿佛凌空乘风而行，不知停在哪里；', 1, 0),
(39, 1, '绝', 'jué', '<动>断，断绝', '余音袅袅，不<b>绝</b>如缕。', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '于是喝酒喝得高兴，敲着船舷唱歌。', 1, 0),
(40, 1, '适', 'shì', '<副>恰好', '惟江上之清风，与山间之明月，耳得之而为声，目遇之而成色，取之无禁，用之不竭，是造物者之无尽藏也，而吾与子之所共<b>适</b>。', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '只有江上的清风和山间的明月，耳朵听到就成为声音，眼睛看到就成为景色，取用它们没有禁令，享用它们不会竭尽，这是大自然无穷无尽的宝藏，是我和你共同享用的东西。', 1, 0),
(41, 2, '之', 'zhī', '<助>助词，的', '壬戌<b>之</b>秋，七月既望，苏子与客泛舟游于赤壁<b>之</b>下。', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '壬戌年秋，七月十六日，苏轼和友人在赤壁下泛舟游览。', 1, 0),
(42, 2, '其', 'qí', '<代>代词，它，指月亮', '浩浩乎如冯虚御风，而不知<b>其</b>所止；', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '飘飘然像脱离尘世、独立存在，飞升成仙。', 1, 0),
(43, 2, '而', 'ér', '<连>表转折，却', '浩浩乎如冯虚御风，<b>而</b>不知其所止；', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '飘飘然像脱离尘世、独立存在，飞升成仙。', 1, 0),
(44, 2, '于', 'yú', '<介>介词，在', '壬戌之秋，七月既望，苏子与客泛舟游<b>于</b>赤壁之下。', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '壬戌年秋，七月十六日，苏轼和友人在赤壁下泛舟游览。', 1, 0),
(45, 2, '乎', 'hū', '<语气>表疑问，吗', '浩浩<b>乎</b>如冯虚御风，而不知其所止；', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '飘飘然像脱离尘世、独立存在，飞升成仙。', 1, 0),
(46, 2, '焉', 'yān', '<兼>兼词，于之，在那里', '少<b>焉</b>，月出于东山之上，徘徊于斗牛之间。', '部编版｜高中必修上册｜第七单元（课内）｜《赤壁赋》', '一会儿月亮从东山升起，在斗宿牛宿之间徘徊。', 1, 0),
(47, 1, '历', 'lì', '<动>经过', '余以乾隆三十九年十二月，自京师乘风雪，<b>历</b>齐河、长清，穿泰山西北谷，越长城之限，至于泰安。', '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '我在乾隆三十九年十二月，从京城乘着风雪，经过齐河、长清，穿过泰山西北的山谷，越过长城的界限，到了泰安。', 1, 0),
(48, 1, '抵', 'dǐ', '<动>到达', NULL, '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '附件将“抵”列入《登泰山记》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(49, 1, '极', 'jí', '<名>尽头', '<b>极</b>天云一线异色，须臾成五采。', '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '天边的云中有一线奇异的色彩，一会儿变成五彩。', 1, 0),
(50, 1, '望', 'wàng', '<动>远看', '<b>望</b>晚日照城郭，汶水、徂徕如画，而半山居雾若带然。', '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '远望夕阳照着城郭，汶水、徂徕山美如图画，半山停留着的雾气像一条白带。', 1, 0),
(51, 1, '始', 'shǐ', '<动>开始', '余<b>始</b>循以入，道少半，越中岭，复循西谷，遂至其巅。', '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '我开始沿着中谷进入，路走不到一半，越过中岭，又沿着西谷走，于是到达山顶。', 1, 0),
(52, 1, '行', 'xíng', '<动>行走', '皇帝<b>行</b>宫在碧霞元君祠东。', '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '皇帝的行宫在碧霞元君祠东边。', 1, 0),
(53, 1, '道', 'dào', '<名>道路', '四十五里，<b>道</b>皆砌石为磴，其级七千有余。', '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '路程四十五里，道路都是石头砌成的台阶，台阶有七千多级。', 1, 0),
(54, 2, '之', 'zhī', '<助>助词，的', '泰山<b>之</b>阳，汶水西流；', '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '泰山的南面，汶水向西流；', 1, 0),
(55, 2, '其', 'qí', '<代>代词，它，指泰山', '<b>其</b>阴，济水东流。', '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '泰山的北面，济水向东流。', 1, 0),
(56, 2, '而', 'ér', '<连>表修饰', '望晚日照城郭，汶水、徂徕如画，<b>而</b>半山居雾若带然。', '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '远望夕阳照着城郭，汶水、徂徕山美如图画，半山停留着的雾气像一条白带。', 1, 0),
(57, 2, '以', 'yǐ', '<介>介词，在', '余<b>以</b>乾隆三十九年十二月，自京师乘风雪，历齐河、长清，穿泰山西北谷，越长城之限，至于泰安。', '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '我在乾隆三十九年十二月，从京城乘着风雪，经过齐河、长清，穿过泰山西北的山谷，越过长城的界限，到了泰安。', 1, 0),
(58, 2, '于', 'yú', '<介>介词，在', '余以乾隆三十九年十二月，自京师乘风雪，历齐河、长清，穿泰山西北谷，越长城之限，至<b>于</b>泰安。', '部编版｜高中必修上册｜第七单元（课内）｜《登泰山记》', '我在乾隆三十九年十二月，从京城乘着风雪，经过齐河、长清，穿过泰山西北的山谷，越过长城的界限，到了泰安。', 1, 0),
(59, 1, '率', 'shuài', '<形>轻率，草率', '子路<b>率</b>尔而对曰：“千乘之国，摄乎大国之间，加之以师旅，因之以饥馑；', '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '子路轻率地回答：“一个有一千辆兵车的国家，夹在大国之间，又有军队侵犯它，接着发生饥荒；', 1, 0),
(60, 1, '方', 'fāng', '<副>正，正在', '由也为之，比及三年，可使有勇，且知<b>方</b>也。', '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '如果让我治理，等到三年，可以使百姓勇敢，并且懂得道义。', 1, 0),
(61, 1, '冠', 'guàn', '<动>行冠礼', '”曰：“莫春者，春服既成，<b>冠</b>者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。', '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '”曾点说：“暮春三月，春衣已经穿上，成年人五六人，儿童六七人，在沂水边洗浴，在舞雩台上吹风，唱着歌回来。', 1, 0),
(62, 1, '让', 'ràng', '<动>谦让', NULL, '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '附件将“让”列入《子路、曾皙、冉有、公西华侍坐》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
