(64, 1, '得', 'dé', '<动>得到，实现', NULL, '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '附件将“得”列入《子路、曾皙、冉有、公西华侍坐》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(65, 1, '安', 'ān', '<副>怎么', NULL, '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '附件将“安”列入《子路、曾皙、冉有、公西华侍坐》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(66, 2, '以', 'yǐ', '<介>因为', '子曰：“<b>以</b>吾一日长乎尔，毋吾<b>以</b>也。', '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '孔子说：“不要因为我年长一些就不说了。', 1, 0),
(67, 2, '之', 'zhī', '<代>代词，这件事', '子路率尔而对曰：“千乘<b>之</b>国，摄乎大国<b>之</b>间，加<b>之</b>以师旅，因<b>之</b>以饥馑；', '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '子路轻率地回答：“一个有一千辆兵车的国家，夹在大国之间，又有军队侵犯它，接着发生饥荒；', 1, 0),
(68, 2, '其', 'qí', '<代>代词，他的', '如<b>其</b>礼乐，以俟君子。', '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '至于礼乐教化，等待贤能的君子来做。', 1, 0),
(69, 2, '而', 'ér', '<连>表修饰', '子路率尔<b>而</b>对曰：“千乘之国，摄乎大国之间，加之以师旅，因之以饥馑；', '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '子路轻率地回答：“一个有一千辆兵车的国家，夹在大国之间，又有军队侵犯它，接着发生饥荒；', 1, 0),
(70, 2, '焉', 'yān', '<语气>语气助词，呢', '”对曰：“非曰能之，愿学<b>焉</b>。', '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '”回答：“不敢说我能做到，只愿学习。', 1, 0),
(71, 2, '乎', 'hū', '<语气>表疑问，吗', '子曰：“以吾一日长<b>乎</b>尔，毋吾以也。', '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '孔子说：“不要因为我年长一些就不说了。', 1, 0),
(72, 2, '则', 'zé', '<副>就', '居<b>则</b>曰：‘不吾知也！', '部编版｜高中必修下册｜第一单元（课内）｜《子路、曾皙、冉有、公西华侍坐》', '你们平时总说：‘没有人了解我！', 1, 0),
(73, 1, '保', 'bǎo', '<动>安抚，安定', '<b>保</b>民而王，莫之能御也。', '部编版｜高中必修下册｜第一单元（课内）｜《齐桓晋文之事》', '安抚百姓而称王，便没有人能抵挡他。', 1, 0),
(74, 1, '辟', 'pì', '<动>开辟', '欲<b>辟</b>土地，朝秦楚，莅中国而抚四夷也。', '部编版｜高中必修下册｜第一单元（课内）｜《齐桓晋文之事》', '想要开辟土地，使秦楚来朝见，统治中原，安抚四方的少数民族。', 1, 0),
(75, 1, '举', 'jǔ', '<动>推及', '<b>举</b>斯心加诸彼而已。', '部编版｜高中必修下册｜第一单元（课内）｜《齐桓晋文之事》', '把这样的心施加到别人身上罢了。', 1, 0),
(76, 1, '度', 'duó', '<动>衡量', '<b>度</b>，然后知长短。', '部编版｜高中必修下册｜第一单元（课内）｜《齐桓晋文之事》', '用尺量，然后知道长短。', 1, 0),
(77, 1, '治', 'zhì', '<动>治理', '<b>治</b>天下可运之掌上。', '部编版｜高中必修下册｜第一单元（课内）｜《齐桓晋文之事》', '治理天下就可以像在手掌上运转东西一样容易。', 1, 0),
(78, 1, '爱', 'ài', '<动>吝惜', '诚有百姓者，王无异于百姓之以王为<b>爱</b>也。', '部编版｜高中必修下册｜第一单元（课内）｜《齐桓晋文之事》', '如果真有百姓，您不要对百姓认为您吝惜感到奇怪。', 1, 0),
