(86, 2, '而', 'ér', '<连>表转折，却', '然<b>而</b>王道之始也。', '部编版｜高中必修下册｜第一单元（课内）｜《齐桓晋文之事》', '这就是王道的开端。', 1, 0),
(87, 2, '于', 'yú', '<介>介词，比', '诚有百姓者，王无异<b>于</b>百姓之以王为爱也。', '部编版｜高中必修下册｜第一单元（课内）｜《齐桓晋文之事》', '如果真有百姓，您不要对百姓认为您吝惜感到奇怪。', 1, 0),
(88, 2, '则', 'zé', '<副>就', '王若隐其无罪而就死地，<b>则</b>牛羊何择焉？', '部编版｜高中必修下册｜第一单元（课内）｜《齐桓晋文之事》', '大王如果怜悯它没有罪却走向死地，那么牛和羊又有什么区别呢？', 1, 0),
(89, 2, '焉', 'yān', '<语气>语气助词，呢', '王若隐其无罪而就死地，则牛羊何择<b>焉</b>？', '部编版｜高中必修下册｜第一单元（课内）｜《齐桓晋文之事》', '大王如果怜悯它没有罪却走向死地，那么牛和羊又有什么区别呢？', 1, 0),
(90, 2, '何', 'hé', '<代>什么', '齐国虽褊小，吾<b>何</b>爱一牛？', '部编版｜高中必修下册｜第一单元（课内）｜《齐桓晋文之事》', '齐国虽然狭小，我怎么会吝惜一头牛呢？', 1, 0),
(91, 1, '解', 'jiě', '<动>分解，剖开', '庖丁为文惠君<b>解</b>牛。', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '厨师丁给文惠君宰牛。', 1, 0),
(92, 1, '中', 'zhòng', '<动>合乎', '手之所触，肩之所倚，足之所履，膝之所踦，砉然向然，奏刀騞然，莫不<b>中</b>音。', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '手接触的地方、肩倚靠的地方、脚踩踏的地方、膝盖顶住的地方，发出砉砉的声响，进刀时发出騞騞的声音，没有不合乎音律。', 1, 0),
(93, 1, '族', 'zú', '<名>筋骨交错的地方', '<b>族</b>庖月更刀，折也。', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '一般厨师一个月换一把刀，因为砍断。', 1, 0),
(94, 1, '发', 'fā', '<动>出，发出声音', '今臣之刀十九年矣，所解数千牛矣，而刀刃若新<b>发</b>于硎。', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '我的刀用了十九年，宰了几千头牛，刀刃好像刚从磨刀石上磨出来。', 1, 0),
(95, 1, '养', 'yǎng', '<动>保养', '吾闻庖丁之言，得<b>养</b>生焉。', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '我听了庖丁的话，懂得养生的道理了。', 1, 0),
(96, 1, '技', 'jì', '<名>技艺', '<b>技</b>盖至此乎？', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '技术怎么能高超到这种程度呢？', 1, 0),
(97, 1, '经', 'jīng', '<名>经脉', '合于《桑林》之舞，乃中《<b>经</b>首》之会。', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '合乎《桑林》舞蹈的节拍，也合乎《经首》乐曲的节奏。', 1, 0),
(98, 2, '之', 'zhī', '<助>助词，的', '手<b>之</b>所触，肩<b>之</b>所倚，足<b>之</b>所履，膝<b>之</b>所踦，砉然向然，奏刀騞然，莫不中音。', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '手接触的地方、肩倚靠的地方、脚踩踏的地方、膝盖顶住的地方，发出砉砉的声响，进刀时发出騞騞的声音，没有不合乎音律。', 1, 0),
(99, 2, '其', 'qí', '<代>代词，它，指牛', '依乎天理，批大郤，导大窾，因<b>其</b>固然，技经肯綮之未尝，而况大軱乎！', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '依照牛体天然的结构，击入大的缝隙，引导刀进入大的空隙，顺着牛体本来的结构，连筋骨经络都没有碰到，更何况大骨呢！', 1, 0),
(100, 2, '而', 'ér', '<连>表承接', '方今之时，臣以神遇<b>而</b>不以目视，官知止<b>而</b>神欲行。', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '现在，我用精神去接触而不用眼睛看，视觉停止了而精神在运行。', 1, 0),
(101, 2, '以', 'yǐ', '<介>因为', '方今之时，臣<b>以</b>神遇而不<b>以</b>目视，官知止而神欲行。', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '现在，我用精神去接触而不用眼睛看，视觉停止了而精神在运行。', 1, 0),
(102, 2, '焉', 'yān', '<兼>兼词，于之，在其中', '吾闻庖丁之言，得养生<b>焉</b>。', '部编版｜高中必修下册｜第一单元（课内）｜《庖丁解牛》', '我听了庖丁的话，懂得养生的道理了。', 1, 0),
(103, 1, '退', 'tuì', '<使动>使……退却', '佚之狐言于郑伯曰：“国危矣，若使烛之武见秦君，师必<b>退</b>。', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '佚之狐对郑伯说：“国家危险了，如果派烛之武去见秦君，秦军一定会撤退。', 1, 0),
(104, 1, '辞', 'cí', '<动>推辞', '<b>辞</b>曰：“臣之壮也，犹不如人；', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '烛之武推辞说：“我年轻时尚且不如别人；', 1, 0),
(105, 1, '鄙', 'bǐ', '<名>边邑', '越国以<b>鄙</b>远，君知其难也，焉用亡郑以陪邻？', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '越过晋国把远方的郑国作为边邑，您知道很困难，为什么要灭亡郑国来增加邻国的土地呢？', 1, 0),
(106, 1, '济', 'jì', '<动>渡过', '且君尝为晋君赐矣，许君焦、瑕，朝<b>济</b>而夕设版焉，君之所知也。', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '况且您曾经给过晋君恩惠，他答应把焦、瑕给您，早晨渡河归晋，晚上就筑城防御，这是您知道的。', 1, 0),
(107, 1, '阙', 'quē', '<动>侵损，削减', '既东封郑，又欲肆其西封，若不<b>阙</b>秦，焉取之？', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '既然向东把郑国作为疆界，又想扩张西部疆界，如果不损害秦国，将从哪里取得土地？', 1, 0),
(108, 1, '图', 'tú', '<动>考虑', '阙秦以利晋，唯君<b>图</b>之。', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '损害秦国来使晋国获利，希望您考虑这件事。', 1, 0),
(109, 1, '亡', 'wáng', '<动>灭亡', '然郑<b>亡</b>，子亦有不利焉！', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '但郑国灭亡，对您也不利啊！', 1, 0),
(110, 1, '知', 'zhì', '<通假>同“智”，明智', '夜缒而出，见秦伯，曰：“秦、晋围郑，郑既<b>知</b>亡矣。', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '夜里用绳子把烛之武从城墙上吊下去，他见到秦穆公说：“秦晋围攻郑国，郑国已经知道要灭亡了。', 1, 0),
(111, 1, '及', 'jí', '<动>赶得上', '微夫人之力不<b>及</b>此。', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '没有那个人的力量，我到不了今天。', 1, 0),
(112, 2, '之', 'zhī', '<助>助词，的', '佚<b>之</b>狐言于郑伯曰：“国危矣，若使烛<b>之</b>武见秦君，师必退。', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '佚之狐对郑伯说：“国家危险了，如果派烛之武去见秦君，秦军一定会撤退。', 1, 0),
(113, 2, '其', 'qí', '<代>代词，它，指郑国', '晋侯、秦伯围郑，以<b>其</b>无礼于晋，且贰于楚也。', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '晋文公和秦穆公包围郑国，因为郑国曾对晋国无礼，并且在晋、楚之间摇摆。', 1, 0),
(114, 2, '而', 'ér', '<连>表承接', '”公曰：“吾不能早用子，今急<b>而</b>求子，是寡人之过也。', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '”郑伯说：“我没有早点任用您，现在危急才求您，这是我的过错。', 1, 0),
(115, 2, '以', 'yǐ', '<介>因为', '晋侯、秦伯围郑，<b>以</b>其无礼于晋，且贰于楚也。', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '晋文公和秦穆公包围郑国，因为郑国曾对晋国无礼，并且在晋、楚之间摇摆。', 1, 0),
(116, 2, '于', 'yú', '<介>介词，对、向', '晋侯、秦伯围郑，以其无礼<b>于</b>晋，且贰<b>于</b>楚也。', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '晋文公和秦穆公包围郑国，因为郑国曾对晋国无礼，并且在晋、楚之间摇摆。', 1, 0),
(117, 2, '焉', 'yān', '<语气>语气助词，呢', '然郑亡，子亦有不利<b>焉</b>！', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '但郑国灭亡，对您也不利啊！', 1, 0),
(118, 2, '夫', 'fū', '<语气>句首语气助词', '<b>夫</b>晋，何厌之有？', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '晋国哪里有满足的时候？', 1, 0),
(119, 2, '与', 'yǔ', '<介>和', '秦伯说，<b>与</b>郑人盟。', '部编版｜高中必修下册｜第二单元（课内）｜《烛之武退秦师》', '秦穆公很高兴，和郑国结盟。', 1, 0),
(120, 1, '军', 'jūn', '<动>驻军，驻扎', '沛公<b>军</b>霸上，未得与项羽相见。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '沛公的军队驻扎在霸上，还没有能够和项羽相见。', 1, 0),
(121, 1, '倍', 'bèi', '<通假>同“背”，背叛', '愿伯具言臣之不敢<b>倍</b>德也。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '希望您详细说明我不敢背叛恩德。', 1, 0),
(122, 1, '谢', 'xiè', '<动>道歉', '旦日不可不蚤自来<b>谢</b>项王。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '明天早晨不能不早些亲自来向项王道歉。', 1, 0),
(123, 1, '坐', 'zuò', '<动>坐下', '项王、项伯东向<b>坐</b>；', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '项王、项伯面向东坐，亚父面向南坐。', 1, 0),
(124, 1, '辞', 'cí', '<动>推辞', '臣死且不避，卮酒安足<b>辞</b>！', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '我连死都不躲避，一杯酒哪里值得推辞！', 1, 0),
(125, 1, '得', 'dé', '<动>能够', '沛公军霸上，未<b>得</b>与项羽相见。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '沛公的军队驻扎在霸上，还没有能够和项羽相见。', 1, 0),
(126, 1, '度', 'duó', '<动>估计', '<b>度</b>我至军中，公乃入。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '估计我已经回到军营，您才进去。', 1, 0),
(127, 1, '如', 'rú', '<动>及，比得上', '杀人<b>如</b>不能举，刑人<b>如</b>恐不胜。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '杀人唯恐不能杀尽，给人施刑唯恐不能用尽。', 1, 0),
(128, 1, '胜', 'shèng', '<动>尽，完', '杀人如不能举，刑人如恐不<b>胜</b>。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '杀人唯恐不能杀尽，给人施刑唯恐不能用尽。', 1, 0),
(129, 1, '数', 'shuò', '<副>多次', '范增<b>数</b>目项王，举所佩玉玦以示之者三。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '范增多次向项王使眼色，再三举起他佩戴的玉玦给项王看。', 1, 0),
(130, 1, '王', 'wàng', '<使动>称王，让……称王', '范增数目项<b>王</b>，举所佩玉玦以示之者三。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '范增多次向项王使眼色，再三举起他佩戴的玉玦给项王看。', 1, 0),
(131, 2, '之', 'zhī', '<动>动词，到、往', '秦时与臣游，项伯杀人，臣活<b>之</b>。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '秦朝时他和我交往，项伯杀了人，我使他活了下来。', 1, 0),
(132, 2, '其', 'qí', '<代>代词，他的', NULL, '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '附件将“其”列入《鸿门宴》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(133, 2, '而', 'ér', '<连>表承接', '劳苦<b>而</b>功高如此，未有封侯之赏。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '劳苦功高到这种程度，却没有得到封侯的赏赐。', 1, 0),
(134, 2, '以', 'yǐ', '<介>把', '项伯乃夜驰之沛公军，私见张良，具告<b>以</b>事。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '项伯于是连夜骑马赶到沛公的军营，私下会见张良，把事情全部告诉了他。', 1, 0),
(135, 2, '于', 'yú', '<介>介词，在', NULL, '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '附件将“于”列入《鸿门宴》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', 0, 0),
(136, 2, '为', 'wéi', '<介>替，给', '窃<b>为</b>大王不取也。', '部编版｜高中必修下册｜第二单元（课内）｜《鸿门宴》', '我私下认为大王不应该采取这种做法。', 1, 0),
